package com.casystem.onboarding.controller;import com.casystem.onboarding.dto.AuthRequest;import com.casystem.onboarding.model.User;import com.casystem.onboarding.repository.UserRepository;import com.casystem.onboarding.service.*;import jakarta.servlet.http.HttpServletRequest;import org.springframework.http.*;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/auth") @CrossOrigin(origins="*") public class AuthController{private final UserRepository users;private final PasswordEncoder encoder;private final AuditService audit;private final TokenService tokens;public AuthController(UserRepository u,PasswordEncoder e,AuditService a,TokenService t){users=u;encoder=e;audit=a;tokens=t;}@PostMapping("/register")public ResponseEntity<?> register(@RequestBody AuthRequest x,HttpServletRequest req){if(x.email()==null||x.password()==null||x.password().length()<6||x.name()==null||x.name().isBlank())return ResponseEntity.badRequest().body(Map.of("error","Nombre, correo y contraseña (mínimo 6 caracteres) son obligatorios"));if(users.findByEmailAndDeletedFalse(x.email()).isPresent())return ResponseEntity.badRequest().body(Map.of("error","Correo ya registrado"));User u=new User();u.setEmail(x.email().trim().toLowerCase());u.setPassword(encoder.encode(x.password()));u.setName(x.name().trim());users.save(u);audit.log(u.getId(),"Usuario registrado",req.getRemoteAddr());return ResponseEntity.ok(Map.of("message","Cuenta creada"));}@PostMapping("/login")public ResponseEntity<?> login(@RequestBody AuthRequest x,HttpServletRequest req){return users.findByEmailAndDeletedFalse(x.email().trim().toLowerCase()).filter(u->encoder.matches(x.password(),u.getPassword())).<ResponseEntity<?>>map(u->{audit.log(u.getId(),"Inicio de sesión",req.getRemoteAddr());return ResponseEntity.ok(Map.of("name",u.getName(),"role",u.getRole(),"token",tokens.create(u.getId(),u.getEmail())));}).orElseGet(()->ResponseEntity.status(401).body(Map.of("error","Credenciales inválidas")));}}